        Query::put($query, 'ayanamsa', $ayanamsa);
        Query::put($query, 'house_system', $houseSystem);
        Query::put($query, 'lang', $lang);
        Query::put($query, 'locale', $lang);

        return $this->http->requestArray('/v1/chart/planets', $query, $requestOptions);
    }

    /**
     * Birth-time sensitivity (20 credits): for D1 and each varga (default D9,D10,D24) the lagna
     * sign at birth and how many minutes before/after it stays the same, with the neighbouring
     * signs; the same for the Moon's nakshatra and pada; planet sign changes inside the window.
     * window: half-width in minutes (default 120, max 180). Use it to tell users how much a
     * birth-time error matters. Every instant comes as *_local (RFC 3339 with offset) and *_jd
     * (Julian Day, UT); fields that cannot be computed are listed in skipped.
     *
     * Cost: 20 credits per call.
     *
     * Wire names: `houseSystem` -> `house_system`, `topocentricMoon` -> `topocentric_moon`.
     *
     * `GET /v1/chart/sensitivity`
     *
     * @param float $lat Birth place latitude in decimal degrees.
     * @param float $lon Birth place longitude in decimal degrees.
     * @param string $date Birth date (YYYY-MM-DD).
     * @param string $time Birth time (HH:MM, 24-hour, local). Defaults to 12:00.
     * @param string $tz Birth place timezone: IANA name (Asia/Kolkata) or UTC offset (+05:30).
     * @param Ayanamsa|string|null $ayanamsa Ayanamsa (sidereal offset) to use. Defaults to lahiri.
     * @param HouseSystem|string|null $houseSystem House system (`HouseSystem` case or value), sent
     *     as `house_system`.
     * @param int|null $window Half-width of the scan in minutes. Default 120 (±2 h), max 180.
     * @param string|null $vargas Comma-separated vargas besides D1 (D2..D60). Default D9,D10,D24;
     *     at most 16.
     * @param bool|null $topocentricMoon Topocentric Moon for the nakshatra/pada spans, as on
     *     /v1/chart/*. Default false.
     * @param RequestOptions|null $requestOptions Per-call timeout, raw body or onResponse hook.
     *
     * @return array<mixed> The decoded JSON response.
     *
     * @throws LifeAstroException On an API error or a network failure.
     */
